class ServerFeaturesOut(BaseModel):
    """
    What THIS deployment supports, for client preflight (0185).

    Exists because "silently ignore the unknown body field" is the worst
    possible failure for a destructive request: a pre-rewind server would
    reopen the run, delete nothing, and leave the client to discover the skew
    from a missing receipt echo AFTER state changed. Checking here costs one
    cheap GET and turns version skew into a loud error before any write.

    Static by construction — the list is what this build's code does, so there
    is nothing to fetch, cache, or fail. Append feature names; never remove
    one a released client still probes for.
    """

    features: list[str] = Field(..., title='Features')


