class SubNoteWriteOut(BaseModel):
    """
    What a WRITE answers: identity, fullness, version — NEVER the document.

    Scopes are non-hierarchical (permissions.py: a `write` token does not imply
    `read`), so a write response that echoed the body would be a read door the
    READ scope never opened — and on a retention-locked run it would be the
    side door the 402 exists to close. The project PATCH set the precedent: "a
    caller confirming a write reads the project." The dashboard already works
    this way (write, then re-read through the gated GET).
    """

    chars: int = Field(..., title='Chars')
    created_at: AwareDatetime = Field(..., title='Created At')
    id: UUID = Field(..., title='Id')
    limit_chars: int = Field(..., title='Limit Chars')
    limit_tokens: int = Field(..., title='Limit Tokens')
    notes_version: int = Field(..., title='Notes Version')
    remaining_chars: int = Field(..., title='Remaining Chars')
    remaining_tokens: int | None = Field(None, title='Remaining Tokens')
    title: str = Field(..., title='Title')
    tokens: int | None = Field(None, title='Tokens')
    updated_at: AwareDatetime = Field(..., title='Updated At')


