class BinaryNode(BaseModel):
    """
    Two operands, applied pointwise. `mod` is math.fmod (sign follows the
    dividend), `pow` returns NaN where the result would be complex.
    """

    fn: Fn = Field(..., title='Fn')
    left: (
        SeriesNode
        | ConstNode
        | BinaryNode
        | UnaryNode
        | SmoothNode
        | CmpNode
        | CondNode
        | ClampNode
        | CoalesceNode
        | ScanNode
        | WindowNode
        | ShiftNode
        | ReduceNode
    ) = Field(..., discriminator='op', title='Left')
    op: Literal['binary'] = Field(..., title='Op')
    right: (
        SeriesNode
        | ConstNode
        | BinaryNode
        | UnaryNode
        | SmoothNode
        | CmpNode
        | CondNode
        | ClampNode
        | CoalesceNode
        | ScanNode
        | WindowNode
        | ShiftNode
        | ReduceNode
    ) = Field(..., discriminator='op', title='Right')


class ClampNode(BaseModel):
    """
    Bound a curve to [lo, hi]. Expressible as min(max(x, lo), hi), but that
    reads as arithmetic; this reads as intent, and is one node instead of four
    against the node cap.
    """

    hi: (
        SeriesNode
        | ConstNode
        | BinaryNode
        | UnaryNode
        | SmoothNode
        | CmpNode
        | CondNode
        | ClampNode
        | CoalesceNode
        | ScanNode
        | WindowNode
        | ShiftNode
        | ReduceNode
    ) = Field(..., discriminator='op', title='Hi')
    lo: (
        SeriesNode
        | ConstNode
        | BinaryNode
        | UnaryNode
        | SmoothNode
        | CmpNode
        | CondNode
        | ClampNode
        | CoalesceNode
        | ScanNode
        | WindowNode
        | ShiftNode
        | ReduceNode
    ) = Field(..., discriminator='op', title='Lo')
    op: Literal['clamp'] = Field(..., title='Op')
    operand: (
        SeriesNode
        | ConstNode
        | BinaryNode
        | UnaryNode
        | SmoothNode
        | CmpNode
        | CondNode
        | ClampNode
        | CoalesceNode
        | ScanNode
        | WindowNode
        | ShiftNode
        | ReduceNode
    ) = Field(..., discriminator='op', title='Operand')


class CmpNode(BaseModel):
    """
    A comparison as a 0/1 mask, so it composes with ordinary arithmetic:
    multiply by it to gate a term, or feed it to `cond` as a branch test.
    NaN on either side yields NaN, never a silent False.
    """

    fn: Fn1 = Field(..., title='Fn')
    left: (
        SeriesNode
        | ConstNode
        | BinaryNode
        | UnaryNode
        | SmoothNode
        | CmpNode
        | CondNode
        | ClampNode
        | CoalesceNode
        | ScanNode
        | WindowNode
        | ShiftNode
        | ReduceNode
    ) = Field(..., discriminator='op', title='Left')
    op: Literal['cmp'] = Field(..., title='Op')
    right: (
        SeriesNode
        | ConstNode
        | BinaryNode
        | UnaryNode
        | SmoothNode
        | CmpNode
        | CondNode
        | ClampNode
        | CoalesceNode
        | ScanNode
        | WindowNode
        | ShiftNode
        | ReduceNode
    ) = Field(..., discriminator='op', title='Right')


class CoalesceNode(BaseModel):
    """
    Replace a non-finite result with a fallback. The ONLY node that does not
    propagate NaN — everything else does, so without this a single divide-by-zero
    silently removes that step from the curve rather than showing a chosen value.
    """

    fallback: (
        SeriesNode
        | ConstNode
        | BinaryNode
        | UnaryNode
        | SmoothNode
        | CmpNode
        | CondNode
        | ClampNode
        | CoalesceNode
        | ScanNode
        | WindowNode
        | ShiftNode
        | ReduceNode
    ) = Field(..., discriminator='op', title='Fallback')
    op: Literal['coalesce'] = Field(..., title='Op')
    operand: (
        SeriesNode
        | ConstNode
        | BinaryNode
        | UnaryNode
        | SmoothNode
        | CmpNode
        | CondNode
        | ClampNode
        | CoalesceNode
        | ScanNode
        | WindowNode
        | ShiftNode
        | ReduceNode
    ) = Field(..., discriminator='op', title='Operand')


class CondNode(BaseModel):
    """
    Piecewise selection: `when` non-zero picks `then`, zero picks
    `otherwise`. The guard for divide-by-zero — `cond(b != 0, a / b, 0)` keeps
    the step instead of dropping it as non-finite.
    """

    op: Literal['cond'] = Field(..., title='Op')
    otherwise: (
        SeriesNode
        | ConstNode
        | BinaryNode
        | UnaryNode
        | SmoothNode
        | CmpNode
        | CondNode
        | ClampNode
        | CoalesceNode
        | ScanNode
        | WindowNode
        | ShiftNode
        | ReduceNode
    ) = Field(..., discriminator='op', title='Otherwise')
    then: (
        SeriesNode
        | ConstNode
        | BinaryNode
        | UnaryNode
        | SmoothNode
        | CmpNode
        | CondNode
        | ClampNode
        | CoalesceNode
        | ScanNode
        | WindowNode
        | ShiftNode
        | ReduceNode
    ) = Field(..., discriminator='op', title='Then')
    when: (
        SeriesNode
        | ConstNode
        | BinaryNode
        | UnaryNode
        | SmoothNode
        | CmpNode
        | CondNode
        | ClampNode
        | CoalesceNode
        | ScanNode
        | WindowNode
        | ShiftNode
        | ReduceNode
    ) = Field(..., discriminator='op', title='When')


